mapper.select:
SELECT cs.id, cs.schedule_id AS scheduleId, cs.class_id AS classId, cs.class_name AS className, cs.course_name AS courseName, cs.teacher_name AS teacherName, cs.lesson_date AS lessonDate, cs.start_time AS startTime, cs.end_time AS endTime, cs.reason, cs.status, cs.notify_flag AS notifyFlag, cs.message_id AS messageId, cs.operator_name AS operatorName, cs.suspended_at AS suspendedAt, cs.restored_at AS restoredAt, cs.restored_by AS restoredBy FROM class_suspend cs
AND cs.lesson_date >= #{start} AND cs.lesson_date <= #{end} AND cs.class_id = #{classId} AND cs.status = #{status}
ORDER BY cs.suspended_at DESC, cs.id DESC
